<script setup>
import {computed,ref} from 'vue'
import Icon from '../Icon.vue'
import EducationMotion from '../learning/EducationMotion.vue'
import WhatsAppComposer from './WhatsAppComposer.vue'
const props=defineProps({data:Object,metrics:Object,admin:Boolean,member:Object}),emit=defineEmits(['navigate','room','team'])
const composer=ref(false),scheduleFilter=ref('Upcoming')
const today=computed(()=>props.data.today||new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Colombo'}))
const upcoming=computed(()=>props.data.upcoming||[]),todaySessions=computed(()=>upcoming.value.filter(s=>s.starts_at.slice(0,10)===today.value))
const visibleSessions=computed(()=>(scheduleFilter.value==='Today'?todaySessions.value:upcoming.value).slice(0,4))
const pending=computed(()=>props.data.memberships.filter(l=>l.status==='Pending').length)
const hours=computed(()=>(props.metrics?.scheduled_completed_hours||[]).reduce((n,r)=>n+Number(r.hours||0),0).toFixed(1))
const title=id=>props.data.classrooms.find(r=>r.name===id)?.title||id
const time=s=>String(s).slice(11,16),date=s=>new Date(String(s).slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})
const largest=computed(()=>Math.max(1,...props.data.classrooms.map(r=>r.students||0)))
</script>
<template><section class="provider-overview"><div class="overview-kpis"><article v-for="item in [{label:'Students learning',value:data.students,icon:'Users',detail:'Unique enrolled learners'},{label:admin?'Your teaching team':'Active classrooms',value:admin?data.teachers:data.classrooms.length,icon:admin?'GraduationCap':'BookOpen',detail:admin?'Approved teacher memberships':'Your institute + independent classes'},{label:'Classes today',value:todaySessions.length,icon:'CalendarDays',detail:'Remaining scheduled sessions'},{label:'Teaching hours · this month',value:metrics?hours:'—',icon:'Clock3',detail:'Completed scheduled hours · current month'}]" :key="item.label" class="overview-kpi"><span class="kpi-symbol"><Icon :name="item.icon" :size="21"/></span><span>{{item.label}}</span><strong>{{item.value}}</strong><small>{{item.detail}}</small></article></div>
