span><strong>Plan & monthly invoice</strong><small>Review your package and due dates</small></span><Icon name="ChevronRight" :size="15"/></button></aside></div>
<div class="overview-main-grid overview-lower"><section class="schedule-card"><header><div><span class="eyebrow">TIME WELL SPENT</span><h2>Your teaching schedule</h2></div><div class="schedule-switch"><button v-for="filter in ['Today','Upcoming']" :class="{active:scheduleFilter===filter}" @click="scheduleFilter=filter">{{filter}}</button></div></header><article v-for="s in visibleSessions" :key="s.name" class="overview-session"><div class="session-clock"><strong>{{time(s.starts_at)}}</strong><small>{{date(s.starts_at)}}</small></div><div class="session-line"></div><div class="session-info"><h3>{{s.title}}</h3><p>{{title(s.classroom)}} · {{s.meeting_provider||s.mode}}</p><small>{{time(s.starts_at)}}–{{time(s.ends_at)}} · Sri Lanka time</small></div><button class="icon-button" aria-label="Open scheduled classroom" @click="emit('room',s.classroom)"><Icon name="ArrowUpRight" :size="19"/></button></article><div v-if="!visibleSessions.length" class="schedule-empty"><Icon name="Sun" :size="30"/><h3>A little breathing room.</h3><p>{{scheduleFilter==='Today'?'No more classes scheduled today.':'Your next scheduled classes will appear here.'}}</p></div><button class="text-button" @click="emit('navigate','schedule')">View full schedule <Icon name="ArrowRight" :size="16"/></button></section><section class="class-pulse"><header><span class="eyebrow">{{admin?'ACROSS YOUR INSTITUTE':'YOUR LEARNING COMMUNITIES'}}</span><h2>Classroom pulse</h2></header><article v-for="r in data.classrooms.slice(0,4)" :key="r.name"><div><button @click="emit('room',r.name)">{{r.title}}</button><span>{{r.students||0}} {{r.students===1?'student':'students'}}</span></div><div class="class-size-track"><span :style="{width:((r.students||0)/largest*100)+'%'}"></span></div></article><p v-if="!data.classrooms.length">Create your first classroom to begin.</p><small>Relative class size · active enrolments</small><button class="text-button" @click="emit('navigate','classrooms')">All {{data.classrooms.length}} classrooms <Icon name="ArrowRight" :size="16"/></button></section></div><WhatsAppComposer v-if="composer" :rooms="data.classrooms" @close="composer=false"/></section></template>
